<?php require 'config.php'; require 'layout.php';
$total=(int)db()->query('SELECT COUNT(*) FROM volunteers')->fetchColumn(); $pages=max(1,(int)ceil($total/50)); $page=max(1,min($pages,(int)($_GET['page']??1))); $offset=($page-1)*50;
$s=db()->prepare('SELECT * FROM volunteers ORDER BY volunteer_id DESC LIMIT :limit OFFSET :offset'); $s->bindValue(':limit',50,PDO::PARAM_INT); $s->bindValue(':offset',$offset,PDO::PARAM_INT); $s->execute(); $rows=$s->fetchAll();
top('Volunteer directory'); ?>
<div class="d-flex flex-wrap gap-3 justify-content-between align-items-center mb-4"><div><div class="eyebrow">PEOPLE MAKING A DIFFERENCE</div><h1 class="mt-2">Our volunteers</h1><p class="text-secondary mb-0">Manage registrations, availability and ways to help.</p></div><a href="index.php" class="btn btn-primary px-4">+ Register volunteer</a></div>
<?php if(isset($_SESSION['notice'])): ?><div class="alert alert-success" role="status"><?=e($_SESSION['notice'])?></div><?php unset($_SESSION['notice']); endif ?>
<div class="panel p-0 overflow-hidden"><div class="d-flex justify-content-between p-4 border-bottom"><strong><?=number_format($total)?> registrations</strong><span class="text-secondary">Latest registration first · 50 per page</span></div><div class="table-responsive"><table class="table align-middle mb-0"><caption class="px-4">Volunteer directory — page <?=$page?> of <?=$pages?></caption><thead><tr><?php foreach(['ID','Volunteer Name','IC Number','Contact Number','Email Address','Service Category','Available Date','Actions'] as $label): ?><th scope="col"><?=e($label)?></th><?php endforeach ?></tr></thead><tbody>
<?php foreach($rows as $row): ?><tr><td class="text-secondary">#<?=$row['volunteer_id']?></td><?php foreach(FIELDS as $field): ?><td><?=e($row[$field])?></td><?php endforeach ?><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?=$row['volunteer_id']?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?=$row['volunteer_id']?>">Delete</a></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="8" class="text-center py-5"><h2 class="h4">A community starts with one person.</h2><p class="text-secondary">No volunteers registered yet.</p><a href="index.php" class="btn btn-primary">Add the first volunteer</a></td></tr><?php endif ?></tbody></table></div>
<div class="p-4 d-flex flex-wrap gap-3 justify-content-between align-items-center"><span class="small text-secondary">Showing <?=$total?$offset+1:0?>–<?=min($offset+50,$total)?> of <?=$total?></span><nav aria-label="Volunteer pages"><ul class="pagination mb-0"><li class="page-item <?=$page===1?'disabled':''?>"><a class="page-link" href="?page=<?=max(1,$page-1)?>" <?=$page===1?'aria-disabled="true" tabindex="-1"':''?>>Previous</a></li><?php for($i=1;$i<=$pages;$i++): ?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="?page=<?=$i?>" <?=$i===$page?'aria-current="page"':''?>><?=$i?></a></li><?php endfor ?><li class="page-item <?=$page===$pages?'disabled':''?>"><a class="page-link" href="?page=<?=min($pages,$page+1)?>" <?=$page===$pages?'aria-disabled="true" tabindex="-1"':''?>>Next</a></li></ul></nav></div></div><?php bottom(); ?>
